import json
import csv

# Load fees
with open('data/fees.json') as f:
    fees = json.load(f)

# Merchant data
merchant_name = 'Belles_cookbook_store'
merchant_account_type = 'R'
merchant_mcc = 5942
merchant_capture_delay_raw = '1'  # maps to '<3'

# Map merchant capture_delay to fee rule categories
def map_capture_delay(cd):
    """Map merchant capture_delay value to fee rule category."""
    if cd == 'immediate':
        return 'immediate'
    elif cd == 'manual':
        return 'manual'
    else:
        cd_int = int(cd)
        if cd_int < 3:
            return '<3'
        elif 3 <= cd_int <= 5:
            return '3-5'
        else:  # >5
            return '>5'

merchant_capture_delay = map_capture_delay(merchant_capture_delay_raw)

