    merchant_volume_cat = '100k-1m'
elif monthly_volume_total < 5000000:
    merchant_volume_cat = '1m-5m'
else:
    merchant_volume_cat = '>5m'

# Determine fraud level category
if monthly_fraud_level_pct < 7.2:
    merchant_fraud_cat = '<7.2%'
elif monthly_fraud_level_pct < 7.7:
    merchant_fraud_cat = '7.2%-7.7%'
elif monthly_fraud_level_pct <= 8.3:
    merchant_fraud_cat = '7.7%-8.3%'
else:
