tx_card_schemes = {'TransactPlus', 'GlobalCard', 'NexPay', 'SwiftCharge'}
tx_is_credits = {False, True}
tx_acis = {'A', 'C', 'D', 'F', 'G'}
tx_intracountry = {False}  # all international

# Matching functions
def matches_account_type(rule_at, merchant_at):
    """rule_at: list from rule, merchant_at: string. null/empty means match all."""
    if rule_at is None or len(rule_at) == 0:
        return True
    return merchant_at in rule_at

def matches_capture_delay(rule_cd, merchant_cd):
    if rule_cd is None:
        return True
    return rule_cd == merchant_cd

def matches_monthly_fraud_level(rule_mf, merchant_mf_cat):
    if rule_mf is None:
        return True
    return rule_mf == merchant_mf_cat

def matches_monthly_volume(rule_mv, merchant_mv_cat):
    if rule_mv is None:
        return True
    return rule_mv == merchant_mv_cat

def matches_mcc(rule_mcc, merchant_mcc):
    if rule_mcc is None or len(rule_mcc) == 0:
        return True
    return merchant_mcc in rule_mcc

def matches_card_scheme(rule_cs):
    if rule_cs is None:
        return True
    return rule_cs in tx_card_schemes

def matches_is_credit(rule_ic):
    if rule_ic is None:
        return True
    return rule_ic in tx_is_credits

def matches_aci(rule_aci):
    if rule_aci is None or len(rule_aci) == 0:
        return True
    # Check if any ACI in rule matches any transaction ACI
    return bool(set(rule_aci) & tx_acis)

def matches_intracountry(rule_ic_val):
    if rule_ic_val is None:
        return True
    # rule_ic_val is 0.0 (False) or 1.0 (True)
    rule_ic_bool = bool(rule_ic_val)
    return rule_ic_bool in tx_intracountry

